package dashboard.enterprise.agent.llm.runtime;import dashboard.enterprise.agent.llm.audit.LlmAuditStore;import dashboard.enterprise.agent.llm.model.*;import dashboard.enterprise.agent.llm.policy.LlmPermission;import dashboard.enterprise.agent.llm.provider.LlmProvider;import dashboard.enterprise.agent.llm.resolution.LlmProviderResolver;import dashboard.enterprise.agent.llm.validation.StructuredOutputValidator;import dashboard.enterprise.agent.model.AgentContext;import java.time.Instant;import java.util.*;public final class LlmRuntime{private final LlmProviderResolver resolver;private final LlmAuditStore audit;private final StructuredOutputValidator validator;public LlmRuntime(LlmProviderResolver r,LlmAuditStore a,StructuredOutputValidator v){resolver=r;audit=a;validator=v;}public LlmResponse generate(AgentContext context,LlmRequest request,LlmPermission permission,boolean approved,Set<String> requiredFields)throws Exception{if(permission==LlmPermission.PROHIBITED)throw new SecurityException("LLM capability is prohibited: "+request.capabilityId());if(permission==LlmPermission.WRITE_WITH_APPROVAL&&!approved)throw new SecurityException("Human approval required for LLM capability: "+request.capabilityId());LlmProvider provider=resolver.resolve(request);long start=System.nanoTime();LlmResponse response=provider.generate(context,request);long latency=(System.nanoTime()-start)/1_000_000;validator.validate(response,requiredFields);audit.append(new LlmAuditEvent("mapaf.llm.audit/v1",Instant.now().toString(),context.correlationId(),request.requestId(),provider.providerId(),response.modelId(),request.capabilityId(),response.successful()?"SUCCESS":"FAILED",latency,response.usage(),Map.of("actor",context.actor())));return response;}}
